      cursor: pointer;
      box-shadow: 0 16px 36px rgba(33, 212, 167, 0.22);
      transition: transform 160ms ease, box-shadow 160ms ease;
    }

    button:hover {
      transform: translateY(-2px);
      box-shadow: 0 20px 44px rgba(33, 212, 167, 0.3);
    }

    @media (max-width: 680px) {
      body {
        padding: 28px 14px;
      }

      .choice-grid {
        grid-template-columns: 1fr;
      }

      .question-header,
      .actions {
        align-items: stretch;
        flex-direction: column;
      }

      button {
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <main id="root" class="quiz-app"></main>

  <script>
    const quizData = [
      {
        id: "language-types",
        prompt: "Which of these are programming languages?",
        helpText: "Select every option that is commonly used to write software, scripts, or applications.",
        choices: ["Python", "HTML", "JavaScript", "CSS"]
      },
      {
        id: "compiled-languages",
        prompt: "Which languages are commonly compiled before execution?",
        choices: ["C", "Rust", "TypeScript", "Markdown"]
      },
      {
        id: "web-languages",
        prompt: "Which languages are frequently used in web development?",
        choices: ["JavaScript", "PHP", "Ruby", "SQL"]
      }
    ];

    function Choice({ questionId, choice }) {
      const value = choice.toLowerCase().replace(/[^a-z0-9]+/g, "-");

      return `
        <label class="choice">
          <input type="checkbox" name="${questionId}" value="${value}">
          <span>${choice}</span>
        </label>
      `;
    }

    function Question({ question, index }) {
      const helpText = question.helpText
        ? `<p class="help-text" id="${question.id}-help">${question.helpText}</p>`
        : "";
      const describedBy = question.helpText ? ` aria-describedby="${question.id}-help"` : "";

      return `
        <div class="form-field">
          <div class="question-header">
            <div class="question-number" aria-hidden="true">${index + 1}</div>
            <div>
              <h2 class="question-title" id="${question.id}-label">${question.prompt}</h2>
              ${helpText}
            </div>
          </div>
          <fieldset class="choice-grid" aria-labelledby="${question.id}-label"${describedBy}>
            ${question.choices.map((choice) => Choice({ questionId: question.id, choice })).join("")}
          </fieldset>
        </div>
      `;
    }

    function QuizApp({ questions }) {
      return `
        <section class="hero" aria-labelledby="quiz-title">
          <p class="eyebrow">Multi-select quiz</p>
          <h1 id="quiz-title">Computer Languages</h1>
          <p class="intro">Test your knowledge of languages used across software, systems, data, and the web. Some questions may have more than one correct answer.</p>
        </section>
        <section class="quiz-card">
          <form id="quiz-form">
            ${questions.map((question, index) => Question({ question, index })).join("")}
            <div class="actions">
              <p class="status" id="status" role="status"></p>
              <button type="submit">Submit answers</button>
            </div>
          </form>
        </section>
      `;
    }

    document.getElementById("root").innerHTML = QuizApp({ questions: quizData });

    document.getElementById("quiz-form").addEventListener("submit", (event) => {
      event.preventDefault();

      const totalSelected = document.querySelectorAll("input[type='checkbox']:checked").length;
      const status = totalSelected === 1 ? "answer" : "answers";
      document.getElementById("status").textContent = `Submitted ${totalSelected} selected ${status}.`;
    });
  </script>
</body>
</html>
